    <h1>Cookout Batch Card Sorter</h1>
    <div id="toast" class="toast">Checklist copied!</div>

    <!-- Entry Form -->
    <div class="form-container">
        <div class="form-row">
            <input type="text" id="dishName" placeholder="Dish Name (e.g., Smash Burgers)" required>
        </div>
        <div class="form-row">
            <input type="text" id="batchSize" placeholder="Batch Size (e.g., 20 patties)">
            <input type="text" id="prepWindow" placeholder="Prep Window (e.g., 2:00 PM - 2:30 PM)">
        </div>
        <div class="form-row">
            <select id="laneSelect">
                <option value="grill">Grill Lane</option>
                <option value="side">Side Lane</option>
                <option value="drink">Drink Lane</option>
                <option value="dessert">Dessert Lane</option>
            </select>
        </div>
        <div class="form-row">
            <textarea id="servingNotes" placeholder="Serving notes / captions..." rows="2"></textarea>
        </div>
        <button onclick="addCard()">Add Dish Card</button>
    </div>

