        <div class="lane lane-side" id="lane-side">
            <div class="lane-header"><span>Sides</span><span class="count" id="count-side">0</span></div>
            <div class="card-list" id="list-side"></div>
        </div>

        <!-- Drinks -->
        <div class="lane lane-drink" id="lane-drink">
            <div class="lane-header"><span>Drinks</span><span class="count" id="count-drink">0</span></div>
            <div class="card-list" id="list-drink"></div>
        </div>

