        function addCard() {
            const name = document.getElementById('dishName').value.trim();
            const batch = document.getElementById('batchSize').value.trim();
            const prep = document.getElementById('prepWindow').value.trim();
            const lane = document.getElementById('laneSelect').value;
            const notes = document.getElementById('servingNotes').value.trim();

            if (!name) return;

