            if (items.length === 0) return;

            const laneTitles = { grill: 'GRILL', side: 'SIDES', drink: 'DRINKS', dessert: 'DESSERTS' };
            let text = `🔥 COOKOUT PREP & CAPTION CHECKLIST 🔥\n\n`;

            ['grill', 'side', 'drink', 'dessert'].forEach(lane => {
                const laneItems = items.filter(item => item.lane === lane);
                if (laneItems.length > 0) {
                    text += `--- ${laneTitles[lane]} ---\n`;
                    laneItems.forEach(item => {
                        text += `[ ] ${item.name}`;
                        if (item.batch) text += ` (Batch: ${item.batch})`;
                        if (item.prep) text += ` [Window: ${item.prep}]`;
                        text += `\n`;
                        if (item.notes) text += `    📝 Notes: ${item.notes}\n`;
                    });
                    text += `\n`;
                }
            });

            navigator.clipboard.writeText(text.trim()).then(showToast);
        }

        function renderCards() {
            const lists = {
                grill: document.getElementById('list-grill'),
                side: document.getElementById('list-side'),
                drink: document.getElementById('list-drink'),
                dessert: document.getElementById('list-dessert')
            };

            const counts = { grill: 0, side: 0, drink: 0, dessert: 0 };

            // Clear existing
            Object.values(lists).forEach(list => list.innerHTML = '');

            items.forEach(item => {
                counts[item.lane]++;

                const card = document.createElement('div');
                card.className = 'card';

                let metaText = [];
                if (item.batch) metaText.push(`Batch: ${item.batch}`);
                if (item.prep) metaText.push(`Prep: ${item.prep}`);

                card.innerHTML = `
                    <div class="card-title">${item.name}</div>
                    ${metaText.length > 0 ? `<div class="card-meta">${metaText.join(' | ')}</div>` : ''}
                    ${item.notes ? `<div class="card-notes">${item.notes}</div>` : ''}
                    <div class="card-actions">
                        <button class="btn-small" onclick="moveCard('${item.id}', 'prev')">←</button>
                        <button class="btn-small" onclick="moveCard('${item.id}', 'next')">→</button>
                        <button class="btn-small btn-delete" onclick="deleteCard('${item.id}')">Delete</button>
                    </div>
                `;

                if (lists[item.lane]) {
                    lists[item.lane].appendChild(card);
                }
            });

            // Update Counts
            Object.keys(counts).forEach(lane => {
                document.getElementById(`count-${lane}`).innerText = counts[lane];
            });
        }

        // Initial setup
        renderCards();
    </script>
</body>
</html>

