    </div>

    <script>
        let items = JSON.parse(localStorage.getItem('cookout_items')) || [];

        function saveData() {
            localStorage.setItem('cookout_items', JSON.stringify(items));
            renderCards();
        }

        function addCard() {
            const nameInput = document.getElementById('dishName');
            const batchInput = document.getElementById('batchSize');
            const prepInput = document.getElementById('prepWindow');
            const laneSelect = document.getElementById('laneSelect');
            const notesInput = document.getElementById('servingNotes');

            const name = nameInput.value.trim();
            const batch = batchInput.value.trim();
            const prep = prepInput.value.trim();
            const lane = laneSelect.value;
            const notes = notesInput.value.trim();

            if (!name) return;

            const newItem = {
                id: Date.now().toString(),
                name,
                batch,
                prep,
                lane,
                notes
            };

            items.push(newItem);
            saveData();

            nameInput.value = '';
            batchInput.value = '';
            prepInput.value = '';
            notesInput.value = '';
        }

        function deleteCard(id) {
            items = items.filter(item => item.id !== id);
            saveData();
        }

        function moveCard(id, direction) {
            const laneOrder = ['grill', 'side', 'drink', 'dessert'];
            const item = items.find(i => i.id === id);
            if (!item) return;

            let currentIndex = laneOrder.indexOf(item.lane);
            if (direction === 'next' && currentIndex < laneOrder.length - 1) {
                item.lane = laneOrder[currentIndex + 1];
            } else if (direction === 'prev' && currentIndex > 0) {
                item.lane = laneOrder[currentIndex - 1];
            }
            saveData();
        }

        function showToast() {
            const toast = document.getElementById('toast');
            toast.style.display = 'block';
            setTimeout(() => { toast.style.display = 'none'; }, 2000);
