                actionsDiv.appendChild(rightBtn);
                actionsDiv.appendChild(deleteBtn);
                card.appendChild(actionsDiv);

                if (lists[item.lane]) {
                    lists[item.lane].appendChild(card);
                }
            });

            Object.keys(counts).forEach(lane => {
                document.getElementById(`count-${lane}`).textContent = counts[lane];
            });
        }

        document.getElementById('addCardBtn').addEventListener('click', addCard);
        document.getElementById('copyChecklistBtn').addEventListener('click', copyChecklist);

        renderCards();
